#!/usr/bin/env node

import assert from "node:assert/strict";
import { execFileSync, spawn, spawnSync } from "node:child_process";
import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { existsSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { readPackageVersionFromDir } from "../src/package-root.ts";
import { createExampleRepo } from "../src/test/example-repo.ts";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const roots: string[] = [];

try {
  await run();
} finally {
  for (const root of roots) {
    rmSync(root, { recursive: true, force: true });
  }
}

async function run(): Promise<void> {
  const packDir = await mkdtemp(join(tmpdir(), "comprehende-pack-"));
  roots.push(packDir);
  execFileSync("pnpm", ["pack", "--pack-destination", packDir], { cwd: repoRoot, stdio: "inherit" });

  const version = await readPackageVersionFromDir(repoRoot);
  const tarball = join(packDir, `comprehende-${version}.tgz`);
  assert.equal(existsSync(tarball), true, `expected ${tarball}`);

  const listing = execFileSync("tar", ["-tzf", tarball], { encoding: "utf8" }).split("\n");
  for (const required of ["package/dist/cli/main.js", "package/dist/ui/index.html", "package/skills/comprehende/SKILL.md"]) {
    assert.equal(listing.includes(required), true, `tarball missing ${required}`);
  }
  assert.equal(
    listing.some((path) => path.includes("skills-next")),
    false,
    "tarball must not include skills-next",
  );

  const packedPkg: unknown = JSON.parse(
    execFileSync("tar", ["-xOf", tarball, "package/package.json"], { encoding: "utf8" }),
  );
  const packedDependencies: unknown = isRecord(packedPkg) ? packedPkg.dependencies : undefined;
  assert.deepEqual(Object.keys(packedDependencies ?? {}).sort(), ["zod"], "packed tarball may depend on zod only");

  const installDir = await mkdtemp(join(tmpdir(), "comprehende-install-"));
  roots.push(installDir);
  await writeFile(join(installDir, "package.json"), `${JSON.stringify({ name: "pack-smoke-consumer", private: true }, null, 2)}\n`);
  execFileSync("npm", ["install", tarball, "--omit=dev"], { cwd: installDir, stdio: "inherit" });

  const bin = join(installDir, "node_modules/.bin/comprehende");
  assert.equal(existsSync(bin), true, "installed package must expose the comprehende bin");
  assert.equal(
    existsSync(join(installDir, "node_modules/comprehende/node_modules/@pierre")),
    false,
    "npx install must not pull @pierre/diffs",
  );

  const versionOut = execFileSync(bin, ["--version"], { encoding: "utf8" });
  assert.equal(versionOut.trim(), version, `packed bin --version: ${JSON.stringify(versionOut)}`);

  const work = await mkdtemp(join(tmpdir(), "comprehende-cwd-"));
  roots.push(work);
  const repo = await createExampleRepo(work);
  const dataPath = join(work, "review.json");

  const helpOut = execFileSync(bin, ["--help"], { encoding: "utf8" });
  assert.match(helpOut, /review\s+\[--base/);
  assert.doesNotMatch(helpOut, /^\s+index\s/m);
  const indexOut = spawnSync(bin, ["index", "--base", repo.base, "--head", repo.head], {
    cwd: repo.root,
    encoding: "utf8",
  });
  assert.equal(indexOut.status, 1, "packed bin must reject index");
  assert.match(indexOut.stderr, /Unknown command: index/);

  const reviewOut = execFileSync(bin, ["review", "--base", repo.base, "--head", repo.head, "--data", dataPath], {
    cwd: repo.root,
    encoding: "utf8",
  });
  assert.equal(reviewOut.trim(), dataPath);
  const skeletonRaw: unknown = JSON.parse(await readFile(dataPath, "utf8"));
  assert.ok(isRecord(skeletonRaw), "review skeleton must be a JSON object");
  assert.equal(skeletonRaw.title, "Untitled");
  assert.equal(skeletonRaw.why, undefined);
  assert.equal(skeletonRaw.lookFor, undefined);
  const skeletonGroups = skeletonRaw.groups;
  assert.ok(Array.isArray(skeletonGroups) && isRecord(skeletonGroups[0]));
  const skeletonHunks = skeletonGroups[0]?.hunkRefs;
  assert.ok(Array.isArray(skeletonHunks) && skeletonHunks.length > 0, "review skeleton must list hunk refs");
  const groupId = skeletonGroups[0]?.id;
  assert.equal(typeof groupId, "string");

  const validateOut = execFileSync(bin, ["validate", "--data", dataPath], {
    cwd: repo.root,
    encoding: "utf8",
  });
  assert.match(validateOut, /^ok\s/);

  const child = spawn(bin, ["serve", "--data", dataPath, "--port", "0"], {
    cwd: repo.root,
    stdio: ["ignore", "pipe", "pipe"],
  });
  try {
    const url = await waitForLocalhost(child);
    const health = await fetch(`${url}/api/health`);
    assert.equal(health.status, 200);
    const page = await fetch(url);
    assert.equal(page.status, 200);
    const html = await page.text();
    assert.match(html, /<div id="root">/);
  } finally {
  child.kill("SIGTERM");
    await waitForExit(child);
  }

  const outDir = join(work, "site");
  const exportOut = execFileSync(bin, ["export", "--data", dataPath, "--out", outDir], {
    cwd: repo.root,
    encoding: "utf8",
  });
  assert.equal(existsSync(join(outDir, "index.html")), true, "export must copy the UI");
  assert.equal(existsSync(join(outDir, "api/review.json")), true, "export must write frozen review JSON");
  assert.equal(existsSync(join(outDir, "api/agent/overview.md")), true, "export must write overview agent markdown");
  assert.equal(existsSync(join(outDir, `api/agent/groups/${groupId}.md`)), true, "export must write group agent markdown");
  const overviewMd = await readFile(join(outDir, "api/agent/overview.md"), "utf8");
  assert.match(overviewMd, /git diff --find-renames/);
  assert.match(overviewMd, new RegExp(`\\[groups/${groupId}\\.md\\]\\(groups/${groupId}\\.md\\)`));
  assert.doesNotMatch(overviewMd, /@@ -/);
  assert.equal(overviewMd.includes("+++"), false, "agent markdown must not include patch text");
  assert.equal(existsSync(join(outDir, ".git")), false, "export must not copy git");
  assert.match(exportOut, /\/site/);

  const packedUi = join(installDir, "node_modules/comprehende/dist/ui");
  const packedManifest = JSON.parse(await readFile(join(packedUi, "shiki-langs.json"), "utf8")) as {
    chunks: string[];
  };
  assert.ok(packedManifest.chunks.length > 20, "prebuilt UI must keep every highlighter chunk");
  assert.ok(
    packedManifest.chunks.every((file) => existsSync(join(packedUi, file))),
    "serve UI must keep unused highlighter files on disk",
  );
  assert.ok(
    packedManifest.chunks.some((file) => file.includes("shiki-lang-python")),
    "serve UI must still include unused languages such as python",
  );

  const exportedManifest = JSON.parse(await readFile(join(outDir, "shiki-langs.json"), "utf8")) as {
    chunks: string[];
  };
  const kept = exportedManifest.chunks.filter((file) => existsSync(join(outDir, file)));
  const dropped = exportedManifest.chunks.filter((file) => !existsSync(join(outDir, file)));
  assert.ok(kept.some((file) => file.includes("shiki-lang-typescript")), "export must keep typescript");
  assert.ok(kept.some((file) => file.includes("shiki-lang-markdown")), "export must keep markdown");
  assert.ok(dropped.some((file) => file.includes("shiki-lang-python")), "export must drop unused python");
  assert.ok(dropped.length > kept.length, "export must drop most highlighter files");

  console.log("pack-smoke ok");
}

function waitForLocalhost(child: ReturnType<typeof spawn>): Promise<string> {
  return new Promise((resolve, reject) => {
    let stdout = "";
    let stderr = "";
    const timer = setTimeout(() => {
      reject(new Error(`serve timed out\nstdout:\n${stdout}\nstderr:\n${stderr}`));
    }, 15_000);
    child.stdout?.on("data", (chunk: Buffer) => {
      stdout += chunk.toString();
      const match = stdout.match(/http:\/\/127\.0\.0\.1:\d+/);
      if (match?.[0] !== undefined) {
        clearTimeout(timer);
        resolve(match[0]);
      }
    });
    child.stderr?.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
    });
    child.on("error", (error) => {
      clearTimeout(timer);
      reject(error);
    });
    child.on("exit", (code) => {
      if (code !== 0 && code !== null) {
        clearTimeout(timer);
        reject(new Error(`serve exited ${code}\nstdout:\n${stdout}\nstderr:\n${stderr}`));
      }
    });
  });
}

function waitForExit(child: ReturnType<typeof spawn>): Promise<void> {
  if (child.exitCode !== null) {
    return Promise.resolve();
  }
  return new Promise((resolve) => {
    child.once("exit", () => resolve());
  });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
